import re
lines=open('missing_cells.txt').read().splitlines()
sheets=['Rotation list','Rotation chart','recruiting schools','Requirements']
entries=[]
for line in lines:
    sheet=None
    for s in sheets:
        if line.startswith(s+' '):
            sheet=s; rest=line[len(s)+1:]; break
    parts=rest.split(' ',1); cell=parts[0]; rem=parts[1]
    typ=None
    for marker, typname in [(' s ','s'),(' d ','d'),(' n ','n')]:
        if ' '+marker.strip()+' ' in rem:
            idx=rem.rfind(' '+marker.strip()+' '); value=rem[:idx]; fmt=rem[idx+len(marker):]; typ=typname; break
    if typ=='s': val=value[1:-1] if value.startswith("'") else value
    elif typ=='d':
        m=re.search(r'datetime\.datetime\((\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+)\)', value)
        val=f'{m.group(1)}-{m.group(2)}-{m.group(3)}'
    else: val=value
    entries.append((sheet,cell,val))
with open('parsed_missing.txt','w') as f:
    for s in sheets:
        f.write(f'\n=== {s} count {sum(1 for e in entries if e[0]==s)} ===\n')
